// Extract data from webhook
const { calendarId, date, openingHours, reservationDuration } = $json;

// Get day of week
const dateObj = new Date(date);
const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const dayOfWeek = dayNames[dateObj.getDay()];

const hours = openingHours[dayOfWeek];

if (!hours || hours.closed) {
  return [{
    json: {
      calendarId,
      date,
      availableSlots: [],
      closed: true
    }
  }];
}

return [{
  json: {
    calendarId,
    date,
    openingHours: hours,
    reservationDuration
  }
}];

// Get opening hours from previous node
const config = $('Process Request').first().json;
const events = $input.all();

const { openingHours, reservationDuration } = config;

// Parse opening hours
const [openHour, openMinute] = openingHours.open.split(':').map(Number);
const [closeHour, closeMinute] = openingHours.close.split(':').map(Number);

// Get reserved times from events
const reservedTimes = events
  .map(event => {
    if (event.json.start && event.json.start.dateTime) {
      const startTime = new Date(event.json.start.dateTime);
      return `${String(startTime.getHours()).padStart(2, '0')}:${String(startTime.getMinutes()).padStart(2, '0')}`;
    }
    return null;
  })
  .filter(time => time !== null);

// Generate available slots
const slots = [];
let currentHour = openHour;
let currentMinute = openMinute;

while (currentHour < closeHour || (currentHour === closeHour && currentMinute < closeMinute)) {
  const timeSlot = `${String(currentHour).padStart(2, '0')}:${String(currentMinute).padStart(2, '0')}`;

  if (!reservedTimes.includes(timeSlot)) {
    slots.push(timeSlot);
  }

  // Increment by 30 minutes
  currentMinute += 30;
  if (currentMinute >= 60) {
    currentMinute -= 60;
    currentHour += 1;
  }
}

return [{
  json: {
    availableSlots: slots
  }
}];
